def handle_error(self, req, client, addr, exc):
    request_start = datetime.now()
    addr = addr or ('', -1)  # unix socket case
    if isinstance(exc, (
        InvalidRequestLine, InvalidRequestMethod,
        InvalidHTTPVersion, InvalidHeader, InvalidHeaderName,
        LimitRequestLine, LimitRequestHeaders,
        InvalidProxyLine, ForbiddenProxyRequest,
        InvalidSchemeHeaders,
        SSLError,
    )):

        status_int = 400
        reason = "Bad Request"

        if isinstance(exc, InvalidRequestLine):
            mesg = "Invalid Request Line '%s'" % str(exc)
        elif isinstance(exc, InvalidRequestMethod):
            mesg = "Invalid Method '%s'" % str(exc)
        elif isinstance(exc, InvalidHTTPVersion):
            mesg = "Invalid HTTP Version '%s'" % str(exc)
        elif isinstance(exc, (InvalidHeaderName, InvalidHeader,)):
            mesg = "%s" % str(exc)
            if not req and hasattr(exc, "req"):
                req = exc.req  # for access log
        elif isinstance(exc, LimitRequestLine):
            mesg = "%s" % str(exc)
        elif isinstance(exc, LimitRequestHeaders):
            reason = "Request Header Fields Too Large"
            mesg = "Error parsing headers: '%s'" % str(exc)
            status_int = 431
        elif isinstance(exc, InvalidProxyLine):
            mesg = "'%s'" % str(exc)
        elif isinstance(exc, ForbiddenProxyRequest):
            reason = "Forbidden"
            mesg = "Request forbidden"
            status_int = 403
        elif isinstance(exc, InvalidSchemeHeaders):
            mesg = "%s" % str(exc)
        elif isinstance(exc, SSLError):
            reason = "Forbidden"
            mesg = "'%s'" % str(exc)
            status_int = 403

        msg = "Invalid request from ip={ip}: {error}"
        self.log.warning(msg.format(ip=addr[0], error=str(exc)))
    else:
        if hasattr(req, "uri"):
            self.log.exception("Error handling request %s", req.uri)
        status_int = 500
        reason = "Internal Server Error"
        mesg = ""

    if req is not None:
        request_time = datetime.now() - request_start
        environ = default_environ(req, client, self.cfg)
        environ['REMOTE_ADDR'] = addr[0]
        environ['REMOTE_PORT'] = str(addr[1])
        resp = Response(req, client, self.cfg)
        resp.status = "%s %s" % (status_int, reason)
        resp.response_length = len(mesg)
        self.log.access(resp, req, environ, request_time)

    try:
        util.write_error(client, status_int, reason, mesg)
    except Exception:
        self.log.debug("Failed to send error message.")

def handle(self, listener, client, addr):
    req = None
    try:
        if self.cfg.is_ssl:
            client = sock.ssl_wrap_socket(client, self.cfg)
        parser = http.RequestParser(self.cfg, client, addr)
        req = next(parser)
        self.handle_request(listener, req, client, addr)
    except http.errors.NoMoreData as e:
        self.log.debug("Ignored premature client disconnection. %s", e)
    except StopIteration as e:
        self.log.debug("Closing connection. %s", e)
    except ssl.SSLError as e:
        if e.args[0] == ssl.SSL_ERROR_EOF:
            self.log.debug("ssl connection closed")
            client.close()
        else:
            self.log.debug("Error processing SSL request.")
            self.handle_error(req, client, addr, e)
    except EnvironmentError as e:
        if e.errno not in (errno.EPIPE, errno.ECONNRESET, errno.ENOTCONN):
            self.log.exception("Socket error processing request.")
        else:
            if e.errno == errno.ECONNRESET:
                self.log.debug("Ignoring connection reset")
            elif e.errno == errno.ENOTCONN:
                self.log.debug("Ignoring socket not connected")
            else:
                self.log.debug("Ignoring EPIPE")
    except Exception as e:
        self.handle_error(req, client, addr, e)
    finally:
        util.close(client)

def handle_request(self, listener, req, client, addr):
    environ = {}
    resp = None
    try:
        self.cfg.pre_request(self, req)
        request_start = datetime.now()
        resp, environ = wsgi.create(req, client, addr,
                                    listener.getsockname(), self.cfg)
        # Force the connection closed until someone shows
        # a buffering proxy that supports Keep-Alive to
        # the backend.
        resp.force_close()
        self.nr += 1
        if self.nr >= self.max_requests:
            self.log.info("Autorestarting worker after current request.")
            self.alive = False
        respiter = self.wsgi(environ, resp.start_response)
        try:
            if isinstance(respiter, environ['wsgi.file_wrapper']):
                resp.write_file(respiter)
            else:
                for item in respiter:
                    resp.write(item)
            resp.close()
        finally:
            request_time = datetime.now() - request_start
            self.log.access(resp, req, environ, request_time)
            if hasattr(respiter, "close"):
                respiter.close()
    except EnvironmentError:
        # pass to next try-except level
        util.reraise(*sys.exc_info())
    except Exception:
        if resp and resp.headers_sent:
            # If the requests have already been sent, we should close the
            # connection to indicate the error.
            self.log.exception("Error handling request")
            try:
                client.shutdown(socket.SHUT_RDWR)
                client.close()
            except EnvironmentError:
                pass
            raise StopIteration()
        raise
    finally:
        try:
            self.cfg.post_request(self, req, environ, resp)
        except Exception:
            self.log.exception("Exception in post_request hook")
